#!/usr/bin/env bash
# Rebuild the R5 UI, then apply the exact sidebarlabels1 production overlay.
# Only local OCI archives are written; no image is imported or deployed.
set -Eeuo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "${ROOT}/../.." && pwd)"
R11="${REPO}/deploy/hotfixes/deerflow-skill-authoring-defaults-20260919-r11"
BASE_OCI="${1:?usage: build_production_candidate.sh /absolute/base.oci.tar /absolute/final.oci.tar}"
FINAL_OCI="${2:?usage: build_production_candidate.sh /absolute/base.oci.tar /absolute/final.oci.tar}"
BUILDKIT_ADDR="${BUILDKIT_ADDR:-unix:///run/buildkit/buildkitd.sock}"

case "${BASE_OCI}" in /*) ;; *) echo "base output must be absolute" >&2; exit 2 ;; esac
case "${FINAL_OCI}" in /*) ;; *) echo "final output must be absolute" >&2; exit 2 ;; esac
test "${BASE_OCI}" != "${FINAL_OCI}"
test ! -e "${BASE_OCI}"
test ! -e "${FINAL_OCI}"
test "$(uname -m)" = aarch64
command -v buildctl >/dev/null
command -v python3 >/dev/null

# shellcheck disable=SC1091
source "${R11}/IMAGE_LOCKS.env"
# shellcheck disable=SC1091
source "${ROOT}/IMAGE_LOCKS.env"
test "${NEW_UI_IMAGE}" = "${BASE_WEKNORA_FRONTEND_IMAGE}"
test "${TARGET_WEKNORA_FRONTEND_IMAGE}" = \
  'deerflow.local/weknora-ui:0.8.0-enterprise-sso2-r5-sidebarlabels1-arm64-20260918'

(
  cd "${R11}"
  sha256sum -c PACKAGE.SHA256
)
"${ROOT}/build_oci.sh" "${BASE_OCI}"

LAYOUT="$(mktemp -d)"
trap 'rm -rf -- "${LAYOUT}"' EXIT

# The archive above is generated by our local BuildKit. Reject paths that are
# not ordinary OCI-layout files before placing them in the temporary directory.
python3 - "${BASE_OCI}" "${LAYOUT}" "${BASE_WEKNORA_FRONTEND_IMAGE}" <<'PY'
import hashlib
import json
import pathlib
import sys
import tarfile

archive, root, image = sys.argv[1], pathlib.Path(sys.argv[2]), sys.argv[3]
with tarfile.open(archive, "r:*") as source:
    for member in source:
        name = member.name[2:] if member.name.startswith("./") else member.name
        parts = pathlib.PurePosixPath(name).parts
        if name in ("", ".") and member.isdir():
            continue
        if not parts or name.startswith("/") or ".." in parts or "\\" in name:
            raise SystemExit("unsafe OCI path")
        if not (name in ("index.json", "oci-layout", "blobs", "blobs/sha256")
                or name.startswith("blobs/sha256/")):
            raise SystemExit("unexpected OCI member")
        if member.isdir():
            (root / name).mkdir(parents=True, exist_ok=True)
            continue
        if not member.isfile():
            raise SystemExit("unsupported OCI member type")
        target = root / name
        target.parent.mkdir(parents=True, exist_ok=True)
        with source.extractfile(member) as inp, target.open("xb") as out:
            while True:
                chunk = inp.read(1024 * 1024)
                if not chunk:
                    break
                out.write(chunk)
index = json.loads((root / "index.json").read_text(encoding="utf-8"))
descriptors = index.get("manifests", [])
matches = [item for item in descriptors if
           (item.get("annotations") or {}).get("org.opencontainers.image.ref.name") == image]
descriptor = matches[0] if len(matches) == 1 else descriptors[0] if len(descriptors) == 1 else None
if descriptor is None:
    raise SystemExit("cannot select unique base manifest")
digest = descriptor.get("digest", "")
if not digest.startswith("sha256:"):
    raise SystemExit("unexpected base manifest digest")
blob = root / "blobs" / "sha256" / digest.split(":", 1)[1]
if hashlib.sha256(blob.read_bytes()).hexdigest() != digest.split(":", 1)[1]:
    raise SystemExit("base manifest hash mismatch")
(root / "manifest.digest").write_text(digest + "\n", encoding="ascii")
PY

DIGEST="$(cat "${LAYOUT}/manifest.digest")"
buildctl --addr "${BUILDKIT_ADDR}" build \
  --progress=plain \
  --frontend dockerfile.v0 \
  --local "context=${R11}" \
  --local "dockerfile=${R11}" \
  --oci-layout "weknora_frontend_base=${LAYOUT}" \
  --opt filename=Dockerfile.weknora-frontend \
  --opt platform=linux/arm64 \
  --opt "context:weknora-frontend-base=oci-layout://weknora_frontend_base@${DIGEST}" \
  --output "type=oci,name=${TARGET_WEKNORA_FRONTEND_IMAGE},dest=${FINAL_OCI}"

python3 "${REPO}/release/production-build-alignment-20260928/verify_oci.py" \
  --image "${TARGET_WEKNORA_FRONTEND_IMAGE}" --archive "${FINAL_OCI}"
